    updateCourse: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                /**
                 * @description Identificador del curso. Un valor que no es un UUID se trata como un curso inexistente
                 *     (`404`), igual que el de otro colegio.
                 */
                id: components["parameters"]["CourseId"];
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                /**
                 * @example {
                 *       "name": "1º Primaria Tarde",
                 *       "classes": [
                 *         {
                 *           "id": "0192f5a0-0000-7000-8000-0000000000e1",
                 *           "name": "Grupo A",
                 *           "tutorId": "0192f5a0-0000-7000-8000-0000000000f1"
                 *         },
                 *         {
                 *           "name": "C",
                 *           "tutorId": null
                 *         }
                 *       ]
                 *     }
                 */
                "application/json": components["schemas"]["UpdateCourseRequest"];
            };
        };
        responses: {
            /** @description El curso en su estado final, con las clases en el orden del listado */
            200: {
                headers: {
                    "Cache-Control": components["headers"]["NoStore"];
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "success": true,
                     *       "data": {
                     *         "course": {
                     *           "id": "0192f5a0-0000-7000-8000-0000000000d1",
                     *           "name": "1º Primaria Tarde",
                     *           "createdAt": "2026-10-19T09:30:00.000Z",
                     *           "classes": [
                     *             {
                     *               "id": "0192f5a0-0000-7000-8000-0000000000e3",
                     *               "name": "C",
                     *               "tutor": null
                     *             },
                     *             {
                     *               "id": "0192f5a0-0000-7000-8000-0000000000e1",
                     *               "name": "Grupo A",
                     *               "tutor": null
                     *             }
                     *           ]
                     *         }
                     *       }
                     *     }
                     */
                    "application/json": components["schemas"]["CourseResponse"];
                };
            };
            400: components["responses"]["ValidationError"];
            401: components["responses"]["Unauthorized"];
            404: components["responses"]["CourseNotFound"];
            /**
             * @description Tres casos, que se distinguen por `error.code`. `COURSE_ALREADY_EXISTS`: otro curso del
             *     colegio ya tiene ese nombre, sin distinguir mayúsculas ni espacios sobrantes. `COURSE_CHANGED`:
             *     el cuerpo incluye una clase que ya no pertenece al curso. `PROFESSOR_ALREADY_TUTOR`: un
             *     profesor elegido ya tutoriza una clase que esta edición no libera (de otro curso, o porque
             *     otra petición se la asignó a la vez). En los tres casos no se guarda nada.
             */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            500: components["responses"]["InternalError"];
            503: components["responses"]["ServiceUnavailable"];
        };
    };
